import hashlib, json, os, subprocess, time
import resource
from pathlib import Path
ROOT = Path('/root/.codex/worktrees/f396/medaka')
OUT = Path(__file__).resolve().parent
resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def source_hashes():
    return {str(p.relative_to(ROOT)): sha(p) for folder in ('compiler','stdlib') for p in sorted((ROOT/folder).rglob('*.mdk'))}
def run(label, argv, extra=None):
    env = {k:v for k,v in os.environ.items() if not k.startswith(('MEDAKA_', 'GC_', 'MDK_BYTEBLOCK_'))}
    env.update(JOBS='1')
    if extra: env.update(extra)
    print('START '+label, flush=True)
    start=time.time()
    stdout=OUT/(label+'.stdout'); stderr=OUT/(label+'.stderr')
    with stdout.open('wb') as a, stderr.open('wb') as b:
        p=subprocess.run([str(x) for x in argv], cwd=ROOT, env=env, stdout=a, stderr=b)
    row=dict(label=label,argv=[str(x) for x in argv],cwd=str(ROOT),environment={'JOBS':'1',**(extra or {})},start_unix=start,end_unix=time.time(),exit=p.returncode,stdout=str(stdout),stderr=str(stderr),stdout_sha256=sha(stdout),stderr_sha256=sha(stderr))
    with (OUT/'commands.jsonl').open('a') as f: f.write(json.dumps(row)+'\n')
    print('END '+label+' exit='+str(p.returncode), flush=True)
    if p.returncode: raise SystemExit(p.returncode)
    return stdout.read_text(),stderr.read_text()
